import{R as e,e as i,f as n,U as o}from"./chunks/framework.ywem4qy5.js";const d=JSON.parse('{"title":"SuiteCRM","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/crm/suitecrm.md","filePath":"integrations/crm/suitecrm.md","lastUpdated":1775908585000}'),r={name:"integrations/crm/suitecrm.md"};function a(s,t,l,c,h,g){return i(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="suitecrm" tabindex="-1">SuiteCRM <a class="header-anchor" href="#suitecrm" aria-label="Permalink to &quot;SuiteCRM&quot;">​</a></h1><p>Follow the below steps to connect to the SuiteCRM API.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>CRM</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select SuiteCRM as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-suitecrm-api" tabindex="-1">Step 2. Connect to the SuiteCRM API <a class="header-anchor" href="#step-2-connect-to-the-suitecrm-api" aria-label="Permalink to &quot;Step 2. Connect to the SuiteCRM API&quot;">​</a></h3><ol><li>Login to your SuiteCRM instance.</li><li>Navigate to <strong>Admin</strong> → <strong>OAuth2 Clients and Tokens</strong>.</li><li>Click <strong>Create OAuth2 Client</strong>.</li><li>In the <strong>Redirect URI</strong> field, enter the value from the <strong>Redirect URI</strong> field in Formie.</li><li>Copy the <strong>Client ID</strong> from SuiteCRM and paste in the <strong>Client ID</strong> field in Formie.</li><li>Copy the <strong>Client Secret</strong> from SuiteCRM and paste in the <strong>Client Secret</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Connect</strong> button in the right-hand sidebar.</li><li>You‘ll be redirected to SuiteCRM, where you must approve Formie to access your SuiteCRM account.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration and fill out all required fields.</li><li>Click <strong>Save</strong> to save the form.</li></ol>',10)])])}const m=e(r,[["render",a]]);export{d as __pageData,m as default};
